-- BusBridge Supabase Schema
create extension if not exists "uuid-ossp";
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique, full_name text, avatar_url text, created_at timestamptz default now());
create table if not exists public.bus_routes (id text primary key, bus_number text not null, name text not null, from_stop text not null, to_stop text not null, duration integer, total_stops integer, distance numeric(5,2), frequency text, type text default "Ordinary", is_active boolean default true, source text default "demo", created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.bus_stops (id serial primary key, route_id text references public.bus_routes(id) on delete cascade, stop_order integer not null, name text not null, lat numeric(10,7), lng numeric(10,7), major_stop boolean default false, created_at timestamptz default now());
create table if not exists public.crowd_reports (id uuid primary key default uuid_generate_v4(), route_id text references public.bus_routes(id), bus_number text not null, crowd_level text not null check (crowd_level in ("low","medium","high","very_high")), notes text, reported_at timestamptz default now(), user_id uuid references auth.users(id), source text default "community");
create table if not exists public.issue_reports (id uuid primary key default uuid_generate_v4(), bus_number text not null, category text not null, description text, route_id text references public.bus_routes(id), status text default "submitted", reported_at timestamptz default now(), user_id uuid references auth.users(id));
create table if not exists public.saved_routes (id serial primary key, user_id uuid not null references auth.users(id) on delete cascade, route_id text not null references public.bus_routes(id) on delete cascade, saved_at timestamptz default now(), unique(user_id, route_id));
create table if not exists public.service_alerts (id uuid primary key default uuid_generate_v4(), title text not null, message text not null, severity text default "info", affected_routes text[], start_date date, end_date date, is_active boolean default true, created_at timestamptz default now());
